import 'package:field_sales_mobile/core/db/app_database.dart'; import 'package:flutter_test/flutter_test.dart'; import 'package:sqflite_common_ffi/sqflite_ffi.dart';
void main(){setUpAll((){sqfliteFfiInit();databaseFactory=databaseFactoryFfiNoIsolate;});test('database v4 creates critical tables and indexes',()async{final db=AppDatabase();await db.open();final tables=(await db.db.rawQuery("SELECT name FROM sqlite_master WHERE type='table'" )).map((e)=>e['name']).toSet();expect(tables,containsAll(['sync_queue','local_work_sessions','local_gps_points','privacy_acknowledgements']));final idx=(await db.db.rawQuery("SELECT name FROM sqlite_master WHERE type='index'" )).map((e)=>e['name']).toSet();expect(idx,containsAll(['one_active_session','idx_gps_pending','idx_gps_recorded']));await db.db.close();});}
